{
  "window_id": "w0029",
  "observed_failures": [
    {
      "id": "F1_null_as_empty_string",
      "example_rows": ["078.jpg"],
      "evidence": "Prediction row for 078.jpg has total_amount = \"\" (empty string). The task contract and the current xlsx skill require real nulls (None) for unextractable fields; an empty string is a schema/format violation distinct from a genuine OCR miss.",
      "impact": "Guaranteed amount mismatch for any receipt where extraction fails; converts a soft miss into a hard format error."
    },
    {
      "id": "F2_wrong_total_due_to_qualified_TOTAL_line",
      "example_rows": ["077.jpg (Banh Mi CafE)"],
      "evidence": "Receipt shows a sequence: 'Total (Inclusive of GST): 23.26', then 'Rounding Adj: -0.01', then 'TOTAL: 23.25'. Prediction picked 23.26 (first TOTAL-tier hit) instead of the final rounded TOTAL on the standalone 'TOTAL:' line.",
      "impact": "Any receipt with an intermediate '(Inclusive of GST)/(Incl. GST)'/pre-rounding total followed by a later final TOTAL will be mis-extracted."
    },
    {
      "id": "F3_total_digit_misread",
      "example_rows": ["074.jpg (GL Handicraft, actual 102.00)"],
      "evidence": "Prediction 702.00. The receipt's 'Subtotal: 102.00 / Total Incl. of GST: 102.00 / Total Amt Rounded: 102.00' lines were recognized but the leading digit '1' was OCR'd as '7'. No cross-check across the multiple repeated totals or multiple OCR variants was used to resolve the digit.",
      "impact": "Single-variant OCR errors on isolated digits are not corrected by majority voting over variants or by sanity-checking against repeated total lines."
    },
    {
      "id": "F4_date_digit_misread",
      "example_rows": ["034.jpg (Perniagaan Zheng Hui, actual date 09/03/2018 → 2018-03-09)"],
      "evidence": "Prediction 2018-08-09, i.e. the month digit '3' was read as '8' in one OCR variant and the first matching variant was accepted. No voting across variants, no plausibility check (e.g., consistency with repeated date fields or document time)."
    },
    {
      "id": "F5_grand_total_missed_due_to_rigid_regex",
      "example_rows": ["078.jpg (Thai Delicious, actual 92.80, predicted null)"],
      "evidence": "Trajectory shows OCR variants produced strings like 'Grand Tota.' and 'GrandTota.' where the whitespace/period between 'Grand' and 'Total' was lost or corrupted. The keyword regex required `GRAND\\s*TOTAL` or `\\bTOTAL\\b`, so these corrupted-but-recoverable lines did not match any tier and the extractor correctly fell back to null — but did so because the matcher was too rigid, not because the amount was unreadable."
    },
    {
      "id": "F6_agent_burned_full_iteration_budget",
      "example_rows": [],
      "evidence": "execution_metadata.termination_reason = 'max_iterations' at 65; many iterations were spent hand-debugging two receipts (077 and 078) through ad-hoc per-image variant sweeps instead of generalizing the skill logic.",
      "impact": "Even with hitting 90.9% field accuracy, the method hit iteration cap; a cleaner, more deterministic per-image pipeline from the skill would have terminated earlier and avoided the 'blank cell as \"\"' bug that was likely introduced in late ad-hoc edits."
    }
  ],
  "root_causes": [
    {
      "id": "R1_null_contract_not_enforced_in_code_templates",
      "related_failures": ["F1_null_as_empty_string"],
      "description": "The xlsx skill's 'strict schema' guidance names the rule ('write real nulls, never \"\"/\"None\"/NaN') only as a checklist bullet and in prose. The canonical code pattern shows `None` in the rows list but does not include a post-construction normalization step that coerces any falsy/empty/sentinel value to None, nor a post-write verification that scans the written cells for '' or 'nan'. Agents can easily default to `'' ` in except-branches or when a sub-extractor returns an empty string."
    },
    {
      "id": "R2_total_selection_lacks_specificity_ordering_and_last_match_bias",
      "related_failures": ["F2_wrong_total_due_to_qualified_TOTAL_line"],
      "description": "The current image-ocr skill's `extract_total` iterates tiers in priority order but, within a tier, picks the FIRST matching line. Real receipts place the authoritative TOTAL at the bottom and often precede it with qualified variants ('Total (Inclusive of GST)', 'Total RM Incl. of GST', 'Takeout Total (incl GST)', 'Total Excl. of GST', 'Nett Total vs Total'). No rule prefers (a) the latest match within a tier, (b) standalone unqualified 'TOTAL' over parenthetically-qualified ones, or (c) rounded/final totals over pre-rounding totals. The exclusion list also omits 'INCLUSIVE OF GST', 'INCL GST', 'INCL. OF GST', 'EXCL. OF GST', 'EXCLUDING GST', 'EXCLUSIVE GST', 'ROUNDED TOTAL' vs 'TOTAL ROUNDED', 'TAKEOUT TOTAL', 'SERVICE CHARGE'."
    },
    {
      "id": "R3_no_cross_variant_voting_or_sanity_check",
      "related_failures": ["F3_total_digit_misread", "F4_date_digit_misread"],
      "description": "`multi_pass_ocr` concatenates text from all variants but downstream extractors (`extract_total`, `extract_date`) run once on the concatenated blob and return the first plausible hit. There is no voting across variants, no agreement check across multiple candidate lines (e.g., Subtotal / Total / Rounded Total all showing the same number), and no rejection of implausible OCR artifacts (leading-7 vs leading-1 for an amount that also appears elsewhere as a leading-1)."
    },
    {
      "id": "R4_keyword_regex_too_brittle_for_ocr_noise",
      "related_failures": ["F5_grand_total_missed_due_to_rigid_regex"],
      "description": "Priority regex patterns demand clean whitespace and exact spellings ('GRAND\\s*TOTAL', 'TOTAL\\s*:?\\s*RM'). OCR commonly corrupts separators: 'GrandTota.', 'Grand Tota)', 'T0TAL', 'TOTAL RH', 'TOTAL AMT', 'NET AMOUNT', 'AMOUNT PAYABLE'. There is no normalization step (uppercase + strip punctuation + collapse whitespace + common OCR digit/letter swaps like 0↔O, 1↔I↔l, 5↔S) before matching, and no fuzzy/edit-distance fallback for the 'GRAND TOTAL' tier."
    },
    {
      "id": "R5_no_amount_sanity_filter",
      "related_failures": ["F3_total_digit_misread"],
      "description": "`_last_number` accepts any token matching the number regex on the keyword line, including stray digits from line numbers, dates, phone numbers, or item codes that OCR may have run into the TOTAL line. There is no check that the numeric is monetary-shaped (e.g., has exactly two decimal places or starts with a currency affix), no preference for a two-decimal candidate, and no cross-check that the chosen value agrees with other totals on the receipt."
    },
    {
      "id": "R6_date_disambiguation_single_pass",
      "related_failures": ["F4_date_digit_misread"],
      "description": "`extract_date` walks a fixed pattern list and returns on the first match. There is no disambiguation using additional date-like fields on the receipt (print date, invoice date, transaction date) and no rejection of implausible dates (future, pre-2000, impossible day/month). Running the date extractor on multiple OCR variants and voting would correct many single-digit misreads."
    },
    {
      "id": "R7_skill_does_not_direct_agent_toward_single_shot_pipeline",
      "related_failures": ["F6_agent_burned_full_iteration_budget"],
      "description": "The image-ocr skill provides building blocks (`process_receipt`, `multi_pass_ocr`, `extract_total`, `extract_date`) but no top-level 'canonical batch pipeline' that the agent can call once and write. This invites iterative per-image debugging, which both wastes iterations and introduces regressions such as writing '' instead of None."
    }
  ],
  "skill_defects": [
    {
      "skill": "image-ocr",
      "defects": [
        "`extract_total` picks the first matching line within a tier; should prefer the LAST match and prefer standalone 'TOTAL' over parenthetically-qualified totals.",
        "EXCLUSIONS list is missing common receipt variants: 'INCLUSIVE OF GST', 'INCL GST', 'INCL. OF GST', 'EXCL. OF GST', 'EXCLUSIVE OF GST', 'SERVICE CHARGE', 'SERV CHARGE', 'ROUNDING', 'ROUNDING ADJ', 'ROUNDING ADJUSTMENT', 'TAKEOUT TOTAL', 'TAX AMT', 'TAX AMOUNT', 'TAX TOTAL', 'TOTAL EXCL', 'TOTAL BEFORE', 'CASH', 'VISA', 'MASTERCARD', 'PAYMENT', 'CARD', 'MYR', 'POINTS', 'SAVING', 'DISCOUNT'.",
        "Keyword regex is not applied to a normalized line (no uppercase+punctuation-strip+whitespace-collapse+OCR-swap preprocessing), so OCR-corrupted labels like 'GrandTota.' silently fail the top tier.",
        "No cross-variant voting: `multi_pass_ocr` concatenates variant outputs, but `extract_total`/`extract_date` ignore which variant each candidate came from and do not break ties by agreement count.",
        "No amount sanity filter: the picked number should strongly prefer tokens with exactly two decimal digits, and should be cross-checked against any other matching total-tier lines on the receipt.",
        "Date pipeline returns on first match and does not run across multiple OCR variants with majority voting, so a single misread digit flips the date.",
        "`process_receipt` has no post-condition guarding that results are either a valid formatted string or `None` — any downstream caller that stores the extractor's raw return into an Excel cell can leak '' or stray text.",
        "No top-level batch function that composes sorted-directory iteration + `process_receipt` + a DataFrame row dict, so each agent reinvents (and sometimes breaks) the glue code."
      ]
    },
    {
      "skill": "xlsx",
      "defects": [
        "Strict-schema section lists 'write None, not \"\"/NaN' only as prose and a checklist item; the canonical code pattern does not include an explicit normalization pass (e.g., `df = df.where(df.notna() & (df != ''), None)`) nor a self-verification loop that reads the file back and asserts no cell contains '', 'None', 'NaN', or 'nan'.",
        "No explicit pattern for 'if an upstream extractor can return either a formatted string or None, wrap it with: value = value if isinstance(value, str) and value.strip() else None' before DataFrame construction.",
        "Verification snippet checks that non-null totals match 'N.NN' but does not assert that any cell written as a null is actually read back as NaN/None (catching the '' bug)."
      ]
    },
    {
      "skill": "openai-vision",
      "defects": [
        "Not wrong per se, but for a Tesseract-only environment (no OPENAI_API_KEY asserted in task), the presence of this skill can mislead an agent into attempting a vision-model fallback that is unavailable. The skill should mark its OpenAI dependency as a hard requirement and point back to `image-ocr` when the key is absent."
      ]
    },
    {
      "skill": "pdf",
      "defects": [
        "Not involved in this task; no defects relevant to this window."
      ]
    },
    {
      "skill": "video-frame-extraction",
      "defects": [
        "Not involved in this task; no defects relevant to this window."
      ]
    }
  ],
  "repair_recommendations": [
    {
      "target_skill": "image-ocr",
      "change": "In `extract_total`, iterate tiers in priority order but within each tier collect ALL matches (line, numeric candidate), filter out EXCLUSION keywords first, then choose a single winner using (in order): (a) prefer candidates whose numeric token has exactly two decimal digits, (b) prefer the LAST matching line in reading order, (c) prefer lines whose label is the unqualified form (no parenthetical qualifier such as '(Inclusive of GST)', '(Incl GST)', '(Excl GST)', '(Before Tax)', '(After Discount)'), (d) break further ties by the larger monetary value only when multiple two-decimal candidates agree on the same number elsewhere on the receipt. Fall through to lower-priority tiers only if the current tier yields no candidate.",
      "generalizes_beyond": "Any receipt with multiple TOTAL-like lines (very common in Malaysian/SG/HK receipts with pre-rounding + rounded + GST-inclusive/exclusive variants)."
    },
    {
      "target_skill": "image-ocr",
      "change": "Expand EXCLUSIONS to also include (case-insensitive, substring match on the normalized line): 'INCLUSIVE OF GST', 'INCL GST', 'INCL. GST', 'INCL. OF GST', 'EXCL GST', 'EXCL. GST', 'EXCL. OF GST', 'EXCLUSIVE OF GST', 'EXCLUDING GST', 'EXCLUDING TAX', 'SERVICE CHARGE', 'SERV. CHARGE', 'SERV CHARGE', 'ROUNDING', 'ROUNDING ADJ', 'ROUNDING ADJUSTMENT', 'TAKEOUT TOTAL', 'TAX AMT', 'TAX AMOUNT', 'TAX TOTAL', 'TOTAL EXCL', 'TOTAL BEFORE', 'CASH', 'VISA', 'MASTERCARD', 'CARD', 'PAYMENT', 'MYR', 'POINTS', 'SAVING', 'TOTAL SAVINGS'. Keep the existing set as a subset.",
      "generalizes_beyond": "Prevents selecting subtotals, tax lines, payment lines, card charges, and savings credits as the receipt total across many retail formats."
    },
    {
      "target_skill": "image-ocr",
      "change": "Add a single `_normalize_line(line)` helper that (1) uppercases, (2) collapses runs of whitespace, (3) strips trailing punctuation, (4) replaces common OCR confusions in the LABEL portion only ('0'→'O' when surrounded by letters, 'I'/'l'/'|'→'I', '5'→'S' at word start when the surrounding chars are letters), and apply it to the line before matching both EXCLUSIONS and the priority regex. Keep the ORIGINAL line for numeric extraction so digits are not corrupted. Also loosen the top tier to also match 'GRAND\\s*T[O0]TAL' and 'GRANDT[O0]TAL' (no separator).",
      "generalizes_beyond": "Recovers the top-priority 'GRAND TOTAL' tier when OCR drops the space, replaces O↔0, or appends stray punctuation; stops ~1 entire class of silent regex misses."
    },
    {
      "target_skill": "image-ocr",
      "change": "Change the per-receipt pipeline to run `extract_total` and `extract_date` on EACH OCR variant independently (not on the concatenated text), collect the per-variant results, and return the mode (most common non-None value) with a stable tie-break preferring (a) a candidate that matches a two-decimal money shape, (b) the shortest-edit-distance candidate to the other candidates for digit-level consensus. For dates, require the returned ISO value to be between 2000-01-01 and the current year+1; otherwise drop it and fall back to the next candidate.",
      "generalizes_beyond": "Corrects single-digit OCR flips ('1'↔'7', '3'↔'8', '6'↔'5', '0'↔'8') that affect exactly one variant; this is the modal failure mode for both amount and date fields across receipt OCR."
    },
    {
      "target_skill": "image-ocr",
      "change": "Harden `process_receipt` so that it ALWAYS returns `{'date': <str or None>, 'total_amount': <str or None>}` and never any other falsy sentinel. Wrap each field in a small `_to_null_safe(value)` helper that returns None for '', 'None', 'NaN', 'nan', or any non-string, non-matching value; and assert the two-decimal shape for `total_amount` (regex `^\\d+\\.\\d{2}$`) before returning. Document that callers MUST NOT write the raw dict values through any transformation that would stringify None.",
      "generalizes_beyond": "Eliminates the '' / 'None' / 'nan' leakage class of bugs for any downstream writer (Excel, CSV, JSON)."
    },
    {
      "target_skill": "image-ocr",
      "change": "Add a short top-level 'Canonical Receipt Batch Pipeline' section with a single function (e.g., `build_receipt_rows(directory)`) that: sorts images lexicographically, filters by extension, calls `process_receipt` in a try/except per image, and yields row dicts with keys `filename`, `date`, `total_amount` in that order, with None for any failure. Also document that this function's output is the exact shape the xlsx skill expects for `pd.DataFrame(rows, columns=[...])`.",
      "generalizes_beyond": "Reduces agent iteration budget consumption on glue code and avoids ad-hoc per-image debugging that introduced the '' bug in this run."
    },
    {
      "target_skill": "xlsx",
      "change": "In the strict-schema 'Canonical Pattern' block, add an explicit null-normalization line before writing: `df = df.where(df.notna() & (df.applymap(lambda v: v not in ('', 'None', 'NaN', 'nan'))), None)` (or an equivalent explicit loop), and expand the verification block to assert `check[\"results\"].isna().equals(check[\"results\"].applymap(lambda v: v is None or (isinstance(v, float) and pd.isna(v))))` and that no cell equals '' or 'nan'. Call out that an empty-string cell is a HARD failure under cell-by-cell grading even when the original intent was 'missing value'.",
      "generalizes_beyond": "Protects every strict-schema extraction task where the agent's upstream extractor may emit '' instead of None on failure."
    },
    {
      "target_skill": "xlsx",
      "change": "Add a 'Null Safety Wrapper' snippet: `def _nn(v): return v if isinstance(v, str) and v.strip() not in ('', 'None', 'NaN', 'nan') else None` and recommend wrapping every field value in `_nn(...)` as the rows are built, so the DataFrame never receives a stringified null.",
      "generalizes_beyond": "Any task that must emit real-null cells from imperfect upstream extractors."
    },
    {
      "target_skill": "openai-vision",
      "change": "Add an explicit precondition note at the top: 'Requires OPENAI_API_KEY in the environment. If no key is available (as in many offline receipt-OCR tasks), do NOT attempt this skill; use the `image-ocr` skill instead.' This prevents agents from spending iterations exploring an unavailable fallback."
    }
  ],
  "confidence": {
    "overall": 0.78,
    "per_root_cause": {
      "R1_null_contract_not_enforced_in_code_templates": 0.95,
      "R2_total_selection_lacks_specificity_ordering_and_last_match_bias": 0.9,
      "R3_no_cross_variant_voting_or_sanity_check": 0.75,
      "R4_keyword_regex_too_brittle_for_ocr_noise": 0.7,
      "R5_no_amount_sanity_filter": 0.7,
      "R6_date_disambiguation_single_pass": 0.6,
      "R7_skill_does_not_direct_agent_toward_single_shot_pipeline": 0.7
    },
    "caveats": [
      "Per-field feedback marks correctness but does not reveal oracle values; root causes for 034 (date) and 074/077/078 (amount) are inferred from visible receipt content in the supplied images plus the agent's observed outputs, not from oracle answers.",
      "The empty-string for 078 is directly visible in the prediction payload and is the only failure mode diagnosed with near-certainty.",
      "Recommendations are constrained to edits of the five existing SKILL.md files; they do not propose new skill files or new tools."
    ]
  }
}
